fn iabs(v: i32) -> i32 {
    if v < 0 { -v } else { v }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(8, 100 * 8);
        host::display::state_set(9, 100 * 8);
        host::display::state_set(10, 22);
        host::display::state_set(11, 14);
        host::display::state_set(12, 300 * 8);
        host::display::state_set(13, 260 * 8);
        host::display::state_set(14, -16);
        host::display::state_set(15, 10);
    }
    let mut ax: i32 = host::display::state_get(8);
    let mut ay: i32 = host::display::state_get(9);
    let mut avx: i32 = host::display::state_get(10);
    let mut avy: i32 = host::display::state_get(11);
    let mut bx: i32 = host::display::state_get(12);
    let mut by: i32 = host::display::state_get(13);
    let mut bvx: i32 = host::display::state_get(14);
    let mut bvy: i32 = host::display::state_get(15);
    ax = ax + avx;
    ay = ay + avy;
    bx = bx + bvx;
    by = by + bvy;
    if ax < 18 * 8 { ax = 18 * 8; avx = -avx; }
    if ax > (w - 18) * 8 { ax = (w - 18) * 8; avx = -avx; }
    if ay < 18 * 8 { ay = 18 * 8; avy = -avy; }
    if ay > (h - 18) * 8 { ay = (h - 18) * 8; avy = -avy; }
    if bx < 18 * 8 { bx = 18 * 8; bvx = -bvx; }
    if bx > (w - 18) * 8 { bx = (w - 18) * 8; bvx = -bvx; }
    if by < 18 * 8 { by = 18 * 8; bvy = -bvy; }
    if by > (h - 18) * 8 { by = (h - 18) * 8; bvy = -bvy; }
    let dx: i32 = bx / 8 - ax / 8;
    let dy: i32 = by / 8 - ay / 8;
    if dx * dx + dy * dy < 36 * 36 {
        let tx: i32 = avx;
        avx = bvx;
        bvx = tx;
        let ty: i32 = avy;
        avy = bvy;
        bvy = ty;
        if iabs(dx) > iabs(dy) {
            if dx > 0 { bx = ax + 36 * 8; } else { bx = ax - 36 * 8; }
        } else {
            if dy > 0 { by = ay + 36 * 8; } else { by = ay - 36 * 8; }
        }
    }
    host::display::state_set(8, ax);
    host::display::state_set(9, ay);
    host::display::state_set(10, avx);
    host::display::state_set(11, avy);
    host::display::state_set(12, bx);
    host::display::state_set(13, by);
    host::display::state_set(14, bvx);
    host::display::state_set(15, bvy);
    host::display::clear(0x0e1012);
    host::display::fill_rect(ax / 8 - 18, ay / 8 - 18, 36, 36, 0xe0a030);
    host::display::fill_rect(bx / 8 - 18, by / 8 - 18, 36, 36, 0x4090e0);
    let e: i32 = iabs(avx) + iabs(avy) + iabs(bvx) + iabs(bvy);
    host::display::draw_string(8, 8, "ENERGY", 0x707070, 1);
    host::display::draw_number(70, 8, e, 0xffffff, 1);
    host::display::present();
}
